/* Local-only entry point for the exact, hash-checked 111 prototype. */
'use strict';
const http=require('http'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const {execFile}=require('child_process');
const root=__dirname,outputs=path.join(root,'prototype-output');
const port=8082;
const page=`<!doctype html><html lang="en"><meta charset="utf-8"><title>AYK 111 automatic wiring</title><style>body{background:#080d1d;color:#f3f6fc;font:16px system-ui;margin:40px}main{max-width:850px;margin:auto}button,input{padding:12px;margin:12px 0}button{background:#008cff;color:white;border:0;border-radius:8px}iframe{width:100%;height:65vh;background:white;border:0}a{color:#00a8ff}</style><main><h1>AYK · 111 automatic wiring</h1><p>Reproduce the reviewed 111 prototype: detected terminals, ordered strings, bottom curves and rack-side routes.</p><p>This mode supports the exact supplied 111.vsdx only. Output remains a draft requiring engineering release.</p><form><input type="file" accept=".vsdx" required><button>Generate wiring</button></form><p id="status" role="status"></p><div id="result"></div></main><script>document.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=document.querySelector('button'),s=document.querySelector('#status');b.disabled=true;s.textContent='Detecting ports and generating wiring…';document.querySelector('#result').replaceChildren();try{const f=document.querySelector('input').files[0],r=await fetch('/generate',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.error);s.textContent='Draft generated. Review terminals, routes and cable suitability before release.';for(const [name,url]of Object.entries(j.files)){const a=document.createElement('a');a.href=url;a.textContent='Download '+name;a.download='';document.querySelector('#result').append(a,document.createElement('br'));}const frame=document.createElement('iframe');frame.title='Generated A3 draft';frame.src=j.files['A3 SVG'];document.querySelector('#result').append(frame);}catch(e){s.textContent=e.message;}finally{b.disabled=false;}};</script></html>`;
const server=http.createServer((req,res)=>{
 function json(status,value){res.writeHead(status,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(value));}
 if(req.headers.origin && !['http://127.0.0.1:'+port,'http://localhost:'+port].includes(req.headers.origin))return json(403,{error:'Use the local prototype page.'});
 if(req.method==='GET' && req.url==='/'){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'});return res.end(page);}
 const match=/^\/output\/([a-f0-9-]{36})\/(rack|sheet)$/.exec(req.url || '');
 if(req.method==='GET' && match){const name=match[2]==='rack'?'EXPERIMENTAL-rack-DO-NOT-BUILD.svg':'EXPERIMENTAL-A3-DO-NOT-BUILD.svg';const file=path.join(outputs,match[1],'result',name);if(!fs.existsSync(file))return json(404,{error:'Output not available.'});res.writeHead(200,{'Content-Type':'image/svg+xml','Cache-Control':'no-store','Content-Disposition':'inline; filename="'+name+'"'});return fs.createReadStream(file).pipe(res);}
 if(req.method!=='POST' || req.url!=='/generate')return json(404,{error:'Not found.'});
 const chunks=[];let size=0,tooLarge=false;
 req.on('data',chunk=>{size+=chunk.length;if(size>30*1024*1024){tooLarge=true;chunks.length=0;}else if(!tooLarge)chunks.push(chunk);});
 req.on('end',()=>{
  if(tooLarge || !size)return json(400,{error:'Choose the supplied 111.vsdx (maximum 30 MB).'});
  const id=crypto.randomUUID(),dir=path.join(outputs,id);fs.mkdirSync(dir,{recursive:true});
  const input=path.join(dir,'input.vsdx'),out=path.join(dir,'result');fs.writeFileSync(input,Buffer.concat(chunks));
  execFile('python',[path.join(root,'tests-manual','run-reference-candidate.py'),input,out],{cwd:root,windowsHide:true,timeout:120000,maxBuffer:1024*1024},(error,stdout,stderr)=>{
   if(error){console.error('Prototype generation failed',stdout,stderr);return json(422,{error:'This file could not be generated by the 111 prototype. It requires the exact supplied 111.vsdx and local Python/Pillow/OpenCV. See the server console for details.'});}
   json(200,{files:{'Rack SVG':'/output/'+id+'/rack','A3 SVG':'/output/'+id+'/sheet'}});
  });
 });
});
server.listen(port,'127.0.0.1',()=>console.log('AYK 111 prototype: http://127.0.0.1:'+port));
